const fagverk={schema:"history_go_place_fagverk_v2",level:"standard",status:"curated",intro:"Myntgatakvartalet gjør historiske lag synlige i ett avgrenset bykvartal: et forsvunnet myntverk, et fjernet forsvarslandskap, bevarte staller og nye planer må skilles før de kan ses i sammenheng.",article:["Stedsnavnet peker mot Christian IVs myntverk fra 1628, men de stående bygningene er militæranlegg fra 1800-tallet. Det er derfor avgjørende å skille tomt, forsvunnet institusjon og bevart bygningsmasse.","Bybrannen i 1686 var både ødeleggelse og anledning for festningsmyndighetene. Mynten ble flyttet, og arealet ble innlemmet i et ytre forsvarslandskap med voller og glacis. Senere ble også dette laget fjernet da militære behov endret seg.","Stallene viser at forsvarshistorie også er logistikkhistorie. Hester flyttet mennesker, kanoner og forsyninger. Binderingene på fasadene er konkrete spor, men de sier ikke alene hvor mange hester som sto her eller hvordan arbeidet var organisert.","Kommunens kjøp i 2017 og skoleplanene viser at bevaring ikke betyr uendret bruk. Fredning av bygningene legger rammer for ombygging, mens ny bruk gir nye interesser, aktører og konflikter om tilgjengelighet og kulturminneverdier."],subject_ids:["historie"],emne_ids:["em_his_spor_materialitet","em_his_historiske_lag_i_byrom","em_his_kulturminner_bevaring","em_his_samtid_ettertid_fortelling"],chapter_ids:["historisk_tid_periodisering","kilder_arkiv_spor","minne_kulturarv_historiebruk"],lenses:[{id:"lag-pa-samme-tomt",title:"Historiske lag",prompt:"Hvilke lag er borte, og hvilke kan fortsatt observeres?",subject_id:"historie",emne_id:"em_his_historiske_lag_i_byrom",evidence:"Skill myntverket og vollene fra de stående stall- og kasernebygningene."},{id:"logistikk-og-arbeid",title:"Militær logistikk",prompt:"Hva forteller staller og binderinger om arbeidet som holdt militærmakten i bevegelse?",subject_id:"historie",emne_id:"em_his_spor_materialitet",evidence:"Bruk fasader, Stallgården og kommunens dokumentasjon av hesteanlegget."},{id:"vern-og-ombruk",title:"Vern og ombruk",prompt:"Hvordan kan fredede militærbygg få ny bruk uten at alle historiske spor forsvinner?",subject_id:"historie",emne_id:"em_his_kulturminner_bevaring",evidence:"Sammenhold fredningsstatus, kommunalt eierskap og planene for skole."}],guiding_questions:["Hvorfor er ikke dagens bygninger rester av myntverket?","Hvordan endret bybrannen i 1686 tomtens funksjon?","Hva krevde et militært hesteanlegg av plass, bygninger og arbeid?","Hva kan fredning bevare når bruken samtidig endres?"],concepts:["historiske lag","materialitet","funksjonsskifte","militær logistikk","fredning","ombruk"],observable_traces:[{title:"Binderingene på stallfasadene",observation:"Finn metallringene som ble brukt til å binde hester.",interpretation_boundary:"Ringene dokumenterer hestehold, men ikke alene omfang, tidsbruk eller arbeidsforhold.",source_urls:[urls.osloHistory]},{title:"Stallgårdens skala",observation:"Se hvordan de lange bygningene rammer inn det store gårdsrommet.",interpretation_boundary:"Bygningsformen viser et anlegg, men dateringer og funksjoner må hentes fra kilder.",source_urls:[urls.oppdag,urls.osloCurrent]}],source_urls:[urls.oppdag,urls.osloHistory,urls.osloCurrent,urls.norgesBank,urls.fredning],verified_at:verifiedAt};
