const storyFile=`data/stories/stories_${id}.json`;const story=[{id:`st_${id}_brannen_1686`,quality_profile:"episode_v1",type:"historical_event",title:"Brannen som gjorde myntverk til festningsterreng",year:1686,place_id:id,summary:"Etter bybrannen i 1686 ble myntproduksjonen flyttet og tomten tatt inn i Akershus festnings ytre forsvarsverk.",story:"I 1628 hadde Christian IV lagt et kongelig myntverk ved Akershus. Her ble sølv fra Kongsberg gjort om til mynter, tett på kongemakten og den nye byen.\n\nBybrannen i 1686 brøt dette forløpet. Mynten og bybebyggelsen lå i veien for en ønsket utvidelse av festningen. Produksjonen ble flyttet til Kongsberg, mens voller, vollgrav og glacis overtok tomten.\n\nDet som forsvant, ble likevel bevart i navnet Myntgata. Da forsvarsverkene igjen ble fjernet på 1800-tallet og stallene reist, fortsatte navnet å peke mot et eldre sted som ikke lenger kunne sees.",episode:{actors:["myntmestrene og arbeiderne ved Christiania-mynten","festningsmyndighetene etter bybrannen"],date:"1686",action:"Myntproduksjonen ble flyttet og arealet innlemmet i ytre festningsverk.",consequence:"Det fysiske myntverket forsvant, mens navnet overlevde gjennom senere militær bruk."},sources:[{title:"Oppdag Kvadraturen – Myntgatakvartalet",url:urls.oppdag},{title:"Norges Bank – Christiania-mynten",url:urls.norgesBank}],tags:["myntverk","bybrann","festning","funksjonsskifte"],related_people:["christian_iv"],related_places:["akershus_festning","stattholdergarden"],next_scenes:[{place_id:"akershus_festning",reason:"Festningen overtok arealet som ytre forsvarsterreng etter brannen."}],score:{narrative:3,historical:4,source:4,play_value:3,originality:3,total:17},arc:{start:"Myntverket produserer kongelige mynter ved Akershus.",middle:"Bybrannen skaper et brudd og en kamp om tomtens nye funksjon.",end:"Festningsverkene overtar, men myntnavnet overlever."}}];write(storyFile,story);const sm=read("data/stories/stories_manifest.json");if(!sm.files.some(x=>x.path===storyFile))sm.files.push({category:"historie",entity_id:id,path:storyFile});write("data/stories/stories_manifest.json",sm);const sem=read("data/stories/stories_episode_v1_manifest.json");addOnce(sem.files,storyFile);write("data/stories/stories_episode_v1_manifest.json",sem);

